        "개요": "뮤지컬 글로벌 40주년 + 한국 초연 25주년 기념. 25년간 세 차례(2001·2009·2023)만 올라간 한국어 프로덕션의 네 번째 시즌이고, 이번에는 서울에서 2개월만 올린다. 직전 회차에서는 개막일(12-22)이 윈도우 밖이라 제외됐으나 이번 윈도우에 진입했다. 연말~연초 대극장 최대어.",
