        "평가사유": "[화제성 8점] (확정 →) MMCA 2026년 전시계획(2026-01-05 보도자료)과 KCISA 전시정보통합 API에 2026-11-12~2027-03-31, 국립현대미술관 과천으로 등재. 조지아 오키프를 국내에서 처음 전면에 내세운 전시이고, 대표작인 꽃·사막 연작과 시카고 미술관 소장 주요작이 다수 온다. 알프레드 스티글리츠·찰스 더무스·마스던 하틀리 등 미국 모더니즘 작가군을 함께 묶었다. (추정 →) 출품작 수·관람료는 미공개라 동원 규모는 예측 단계다.\n[독창성 5점] (독점성·희소성·차별 기획 관점) '국내 첫 오키프 전면 전시'는 명확한 최초성이고 시카고 미술관 협력이라는 확보 난이도도 높다. 다만 공개 전시로 독점 취재권이 없어 캘리브레이션 원칙 1에 따라 상단을 제한했다.\n[근접성 7점] (수도권/지방·기간·관객 친숙도) 과천관이라 서울 도심 대비 접근성이 한 단계 낮지만 수도권이고, 4개월 반 장기 개최라 체류 기간은 최상위다. 오키프의 꽃 연작은 대중 친숙도가 높다.\n[영향성 8점] 미술사 기획전은 우리 매체가 지속적으로 다뤄온 영역이라 신뢰도 제고에 기여한다(캘리브레이션 원칙 4). 과천관 개관 40주년 라인업의 핵심이라 미술계 의제화도 기대된다.\n[종합] 강점: 이번 윈도우 전시 최대어급, 국내 최초성, 장기 개최, 매체 정체성 정합. 약점·리스크: 출품작 리스트·관람료 미공개, 과천 입지로 도심 접근성 열위. 직전 회차가 놓쳤던 건이라 경쟁 매체도 같은 시점에 발견할 가능성이 있다. 편성 관점: 같은 겨울의 국립중앙박물관 2대 특별전(《모던 아트의 탄생》·《마리 앙투아네트 스타일》)과 묶어 '2026 겨울 블록버스터 전시 3선' 기획으로 확장 가능.",
