        "평가사유": "[화제성 2점] (추정 →) 푸른향기 2026-10-28 출간, 이정희. 판매지수·별점 미집계, 보도·서평 확인 불가. 저자 인지도도 미상이다.\n[독창성 4점] (독점성·희소성·차별 기획 관점) 시골 책방 운영기는 독립서점 붐과 맞물린 소재로, 현장 취재·책방주 인터뷰라는 차별 각도를 만들 수 있다. 다만 유사 에세이가 이미 여럿 나왔다.\n[근접성 4점] (한국 독자 친숙도·주제 대중성·접근성) 로컬·책방 소재는 호감도가 있으나 독자층이 넓지 않다.\n[영향성 3점] (판매·의제화·영상화 연계·브랜드 기여) 작다.\n[종합] 강점: 현장성 있는 영상 소재. 약점·리스크: 화제 근거 전무, 유사 기획 다수. 편성 관점 — 로컬 코너 보조.",
