        "평가사유": "[화제성 7점] 확정 → 넷플릭스 시리즈 〈참교육〉(2026-06-05 공개, 김무열 주연, 동명 웹툰 원작)의 작가판 무삭제 대본집, 2026-10-28 출간. 공개 직후 글로벌 TOP10 비영어 쇼 1위를 4주 수성하고 2주차 91개국 TOP10, 8주 누적 6,020만 시청수로 넷플릭스 역대 비영어 시리즈 10위에 올랐다(머니투데이·아시아경제 2026-07-29). 원작 IP의 화제성은 이번 배치 최상위급.\n[독창성 4점] 대본집 자체는 흥행작마다 나오는 팬덤 상품이라 희소하지 않다. 다만 이남규·김다희·문종호 3인 작가 인터뷰는 드라마 인터뷰와 결이 달라 독점 각도를 만들 여지가 있다.\n[근접성 6점] 학교폭력·교권 침해·청소년 도박이라는 소재가 국내 사회 이슈와 직결된다. 다만 대본집 구매층은 드라마 팬덤으로 좁아진다.\n[영향성 5점] 시즌2 공식 발표는 아직 확인되지 않았고, 드라마가 이미 소비된 뒤의 파생 상품이라 신규 파급은 제한적이다.\n[종합] 강점: 검증된 글로벌 흥행 IP + 사회 이슈 결합 + 10/28이라는 늦은 출간일로 편성 여유가 있다. 약점·리스크: 드라마 화제의 정점(6~7월)이 지난 후행 아이템이고, ISBN이 전2권 세트 상품이라 단행본 정의에 걸릴 수 있다. 편성 코멘트: '작가 3인이 말하는 참교육' 각도로만 신선하다. 시즌2 발표가 붙으면 가치가 급상승하므로 검증 단계에서 재확인 필요.",
