        "평가사유": "[화제성 8점] (일정 확정 / 동원은 직전 회차 실적 →) 직전 2025 회차가 관람객 9만 4,460명(전년 대비 +53.4%), 56개국 인플루언서 3,567팀 참여, 콘텐츠 누적 4억 5,055만 뷰, 경제효과 1,757억 원을 기록했다. 국내 동원 자체는 10만 명 미만이지만 글로벌 온라인 확산력이 압도적이라 화제성 상위권으로 본다.\n[독창성 8점] (희소성/제휴) 인플루언서 수천 팀을 한자리에 모으는 포맷은 국내에 대체재가 없고, 메인 프로그램인 서울콘 APAN Star Awards(12/29)가 별도 중계 후크를 만든다. 서울시·SBA 주최라 제휴·협찬 진입 여지도 있다.\n[근접성 9점] DDP 일원 + 대부분 무료 + 지하철 직결. 접근성 최상위권.\n[영향성 8점] K-컬처 수출·외래관광객 유치 의제로 매년 전국 뉴스에 노출되고, 새해 카운트다운으로 마무리돼 연말 의제를 선점한다.\n[종합] 강점: 확정 일정 + 검증된 글로벌 확산 실적 + 수도권 무료. 창 안 K-컬처 이벤트 중 확보 가치 1순위. 약점·리스크: 국내 현장 동원은 10만 명 미만이라 '대형 군집'의 체감 규모는 기대보다 작을 수 있고, 12/29~1/1은 취재 인력이 가장 부족한 구간이다. 같은 기간 서울라이트 DDP 겨울이 같은 DDP에서 열려 그림이 겹친다. 편성: 12/29 APAN Star Awards와 12/31~1/1 카운트다운으로 나눠 2회.",
